{"tool":"run","argument":"PYTHONPATH=/workspace/vendor python - <<'PY'
from pathlib import Path
import tarfile,subprocess,json,os
from PIL import Image
root=Path('/workspace');tmp=root/'tmp';diag=root/'diagnostics';diag.mkdir(exist_ok=True)
print('ARCHIVES',[(str(p),p.stat().st_size) for p in tmp.rglob('*.tar.gz')])
java_candidates=list(tmp.glob('**/bin/java'))
for archive in tmp.rglob('*.tar.gz'):
    if archive.stat().st_size>1000000:
        dest=tmp/'java-arm';dest.mkdir(exist_ok=True)
        try:
            with tarfile.open(archive) as t:t.extractall(dest,filter='data')
        except Exception as e:print('EXTRACT_ERROR',str(archive),repr(e))
java_candidates=list((tmp/'java-arm').glob('**/bin/java'))+java_candidates
java=None
for p in java_candidates:
    try:
        r=subprocess.run([str(p),'-version'],capture_output=True,text=True,timeout=10)
        print('JAVA',str(p),r.returncode,r.stderr[-500:])
        if r.returncode==0:java=str(p);break
    except Exception as e:print('JAVA_ERROR',str(p),repr(e))
app=tmp/'audiveris-root/opt/audiveris/lib/app'
for p in app.glob('*.cfg'):print('CONFIG',p.read_text()[:5000])
print('APP_DIRS',[str(p) for p in app.iterdir() if p.is_dir()])
inputs=sorted((root/'inputs').glob('sample-*.png'));enlarged=root/'enlarged';enlarged.mkdir(exist_ok=True)
for p in inputs:
    im=Image.open(p);im.resize((im.width*4,im.height*4),Image.Resampling.LANCZOS).save(enlarged/p.name)
if java:
    cmd=[java,'-Xmx1200m','-Djava.awt.headless=true','-cp',str(app/'*'),'org.audiveris.omr.Main','-batch','-export','-output',str(root/'recognition')]+[str(enlarged/p.name) for p in inputs]
    (diag/'recognition-command.json').write_text(json.dumps(cmd,indent=2))
    env=os.environ.copy();env['HOME']=str(root)
    with (diag/'audiveris.log').open('w') as log:
        try:r=subprocess.run(cmd,stdout=log,stderr=subprocess.STDOUT,env=env,cwd=app,timeout=95);status={'returncode':r.returncode}
        except subprocess.TimeoutExpired:status={'error':'Audiveris exceeded 95 second invocation limit'}
    (diag/'recognition-status.json').write_text(json.dumps(status));print('STATUS',status)
    print((diag/'audiveris.log').read_text()[-16000:])
else:print('BLOCKED: no executable ARM Java runtime')
print('RECOGNITION_FILES',[str(p) for p in (root/'recognition').rglob('*') if p.is_file()])
PY","why":"Run fresh enlarged-image Audiveris recognition using the downloaded ARM Java runtime, retain raw outputs and logs, and diagnose concrete runtime failures before implementing conversion."}
